REPAIR_DASHBOARD = r"""
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AURA — IT & AI Engineering</title>
<style>
:root{color-scheme:dark;--bg:#0b1020;--panel:#141c30;--line:#26334d;--muted:#9aa9c3;--text:#edf3ff;--accent:#9b8cff;--green:#6ee7b7;--red:#fda4af;--amber:#fbbf24}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 system-ui,Segoe UI,sans-serif}main{max-width:1100px;margin:auto;padding:20px 14px 60px}
header,.actions{display:flex;gap:9px;align-items:center;justify-content:space-between;flex-wrap:wrap}h1{font-size:24px;margin:0}h2{font-size:18px;margin:0 0 12px}h3{font-size:15px;margin:16px 0 8px}
.panel{background:var(--panel);border:1px solid var(--line);border-radius:13px;padding:15px;margin-top:14px}.muted,.hint{color:var(--muted)}.hint{font-size:12px}
button,a.btn{border:1px solid var(--line);background:#202b45;color:var(--text);padding:9px 12px;border-radius:9px;cursor:pointer;text-decoration:none;font:inherit}
button.primary{background:var(--accent);color:#11152a;border-color:var(--accent);font-weight:700}button:disabled{opacity:.45;cursor:not-allowed}
input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid var(--line);background:#0e1729;color:var(--text);margin:5px 0 10px;font:inherit}textarea{min-height:90px}
label{display:block;color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.notice{padding:11px;border-radius:9px;background:#202b45;margin-top:10px}.warn{border:1px solid #806321;color:#ffe4a3}.good{color:var(--green)}.bad{color:var(--red)}
table{width:100%;border-collapse:collapse;font-size:13px}td,th{text-align:left;padding:9px 7px;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--muted)}
.scroll{overflow:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#0a1324;border:1px solid var(--line);padding:12px;border-radius:8px;max-height:420px;overflow:auto;font-size:12px}
.hidden{display:none}#login{max-width:460px;margin:60px auto}.pill{font-size:11px;border:1px solid var(--line);border-radius:20px;padding:3px 7px}
@media(max-width:650px){.grid{grid-template-columns:1fr}main{padding:14px 10px 45px}td,th{padding:8px 5px}}
</style></head><body><main>
<section id="login" class="panel"><h1>AURA · IT & AI Engineering</h1><p class="muted">Owner-only repair console · guarded mode</p><label>AURA API key</label><input id="key" type="password" autocomplete="off" placeholder="Masukkan AURA_API_KEY"><button class="primary" id="connect">Connect</button><p class="hint">Key hanya disimpan di session browser ini. Jangan kirim key ke chat atau GitHub.</p><div id="loginmsg" class="hint"></div></section>
<div id="app" class="hidden">
<header><div><h1>IT & AI Engineering <span class="pill">GUARDED</span></h1><div class="muted">CI incidents · triage · patch proposals · Draft PR runner</div></div><div class="actions"><a class="btn" href="/dashboard">Dashboard</a><a class="btn" href="/agents">Agent Console</a><button id="reload">Refresh</button><button id="lock">Lock</button></div></header>
<div class="notice warn"><strong>Safety controls:</strong> this console does not enable AI providers, change billing, merge PRs, or deploy. Proposal generation requires separately enabled and Free-confirmed AI inference. Every triage, generation, approval, and queue action requires an explicit owner confirmation.</div>
<section class="panel"><div class="actions"><h2>CI incident inbox</h2><span id="incidentcount" class="pill">0 incidents</span></div><p class="hint">Only sanitized workflow metadata is shown. Review the original GitHub run before classifying a failure.</p><div id="incidents" class="scroll">Loading…</div></section>
<section class="panel"><div class="actions"><h2>Repair proposals</h2><span id="proposalcount" class="pill">0 proposals</span></div><p class="hint">Review the exact patch and changed paths before approval. Proposals expire; approval receipts are short-lived and single-use.</p><div id="proposals" class="scroll">Loading…</div><div id="proposalview" class="hidden"><h3>Exact patch review</h3><div id="proposalmeta" class="hint"></div><pre id="patch"></pre><div class="actions"><button id="approve" class="primary">Approve this exact patch</button><button id="queue" class="primary hidden">Queue approved patch</button><button id="closeview">Close review</button></div></div></section>
<div id="msg" class="notice hidden"></div>
</div></main>
<script>
let apiKey=sessionStorage.getItem("aura_key")||"",currentProposal=null;
const esc=function(s){return String(s??"").replace(/[&<>"']/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]})};
async function api(path,opts={}){const r=await fetch(path,{...opts,headers:{"Content-Type":"application/json","X-AURA-API-Key":apiKey,...(opts.headers||{})}});let d={};try{d=await r.json()}catch{}if(!r.ok){let msg=d.detail||("HTTP "+r.status);if(typeof msg!=="string")msg=JSON.stringify(msg);throw Error(msg)}return d}
function say(s){const e=document.getElementById("msg");e.textContent=s;e.classList.remove("hidden")}
function table(head,rows){return '<table><thead><tr>'+head.map(x=>'<th>'+x+'</th>').join("")+'</tr></thead><tbody>'+(rows.length?rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join("")+'</tr>').join(""):'<tr><td colspan="'+head.length+'" class="muted">Belum ada data</td></tr>')+'</tbody></table>'}
async function connect(){apiKey=document.getElementById("key").value.trim();if(!apiKey)return;try{await api("/repair/incidents");sessionStorage.setItem("aura_key",apiKey);document.getElementById("login").classList.add("hidden");document.getElementById("app").classList.remove("hidden");await refresh()}catch(e){document.getElementById("loginmsg").textContent=e.message}}
function lock(){sessionStorage.removeItem("aura_key");apiKey="";location.reload()}
async function refresh(){try{const [inc,props]=await Promise.all([api("/repair/incidents"),api("/repair/proposals")]);document.getElementById("incidentcount").textContent=inc.length+" incidents";document.getElementById("proposalcount").textContent=props.length+" proposals";
document.getElementById("incidents").innerHTML=table(["Incident / run","Category","Status","Candidate paths","Owner action"],inc.map(function(x){const paths=JSON.parse(x.candidate_paths_json||"[]");return ['<strong>'+esc(x.summary)+'</strong><div class="hint">#'+esc(x.workflow_run_id)+' · '+esc(x.workflow_name)+' · '+esc(x.head_sha||"") .slice(0,30)+'</div><a target="_blank" rel="noopener" href="'+esc(x.run_url)+'">Open GitHub run ↗</a>','<span class="pill">'+esc(x.triage_category||"unclassified")+'</span>',esc(x.status),paths.map(esc).join("<br>")||"—",'<button onclick="showTriage(\''+esc(x.incident_id)+'\',\''+esc(x.triage_category||"unclassified")+'\',\''+esc(paths.join("\n"))+'\')">Triage</button> <button onclick="generate(\''+esc(x.incident_id)+'\')" '+((x.triage_category==="automated_test_regression"||x.triage_category==="python_syntax_or_import")&&paths.length>0?"":"disabled")+'>Generate proposal</button>']})) ;
document.getElementById("proposals").innerHTML=table(["Proposal","Paths","Status","Expiry","Review"],props.map(function(x){return ['<code>'+esc(x.proposal_id)+'</code><div class="hint">Incident '+esc(x.incident_id)+' · '+esc(x.base_sha).slice(0,12)+'</div>',esc((x.approved_paths||[]).join(", ")), '<span class="pill">'+esc(x.status)+'</span>',esc(new Date(x.expires_at*1000).toLocaleString("id-ID")),'<button onclick="reviewProposal(\''+esc(x.proposal_id)+'\')">Review exact patch</button>']}));}catch(e){say(e.message)}}
function showTriage(id,category,paths){const box=document.createElement("div");box.className="panel";box.id="triagebox";box.innerHTML='<h3>Owner triage · '+esc(id)+'</h3><label>Category</label><select id="triagecat"><option value="">Select category…</option><option value="automated_test_regression">Automated test regression</option><option value="python_syntax_or_import">Python syntax / import</option><option value="dependency_or_security_audit">Dependency / security audit</option><option value="database_schema">Database schema</option><option value="cloudflare_deployment_or_config">Cloudflare deployment / config</option><option value="container_or_runtime">Container / runtime</option><option value="unknown_or_unclassified">Unknown / unclassified</option></select><label>Candidate paths (one per line; only relevant low-risk source/test files)</label><textarea id="triagepaths" placeholder="app/services/example.py&#10;tests/test_example.py">'+esc(paths)+'</textarea><div class="actions"><button class="primary" id="savetr">Save owner triage</button><button id="canceltr">Cancel</button></div><p class="hint">Repair eligibility is limited by server-side allowlists. High-risk categories must have no candidate paths.</p>';
document.querySelector("#incidents").prepend(box);document.getElementById("triagecat").value=category==="unclassified"?"":category;
document.getElementById("canceltr").onclick=function(){box.remove()};document.getElementById("savetr").onclick=async function(){const cat=document.getElementById("triagecat").value,ps=document.getElementById("triagepaths").value.split("\n").map(x=>x.trim()).filter(Boolean);if(!confirm("Konfirmasi triage owner untuk incident "+id+"?"))return;try{const d=await api("/repair/incidents/"+id+"/triage",{method:"POST",body:JSON.stringify({category:cat,candidate_paths:ps,confirm_owner_triage:true})});say("Triage tersimpan · repair eligible: "+d.repair_eligible+" · "+(d.reasons||[]).join(", "));box.remove();await refresh()}catch(e){say(e.message)}}}
async function generate(id){if(!confirm("Buat proposal patch menggunakan provider AI yang sudah diaktifkan secara terpisah? Tidak ada file atau GitHub yang akan ditulis pada tahap ini."))return;try{const d=await api("/repair/incidents/"+id+"/generate-proposal",{method:"POST",body:JSON.stringify({confirm_owner_generation:true,confirm_provider_inference:true})});say("Proposal tersimpan: "+d.proposal_id+" · provider invoked: "+d.provider_invoked);await refresh();await reviewProposal(d.proposal_id)}catch(e){say("Proposal tidak dibuat: "+e.message+" · Periksa konfigurasi provider; console tidak mengaktifkannya.")}}
async function reviewProposal(id){try{const p=await api("/repair/proposals/"+id);currentProposal=p;document.getElementById("proposalview").classList.remove("hidden");document.getElementById("proposalmeta").textContent="Status: "+p.status+" · Base: "+p.base_sha+" · SHA-256: "+p.patch_sha256+" · Paths: "+p.approved_paths.join(", ");document.getElementById("patch").textContent=p.patch_text;document.getElementById("approve").classList.toggle("hidden",p.status!=="proposed");document.getElementById("queue").classList.toggle("hidden",p.status!=="approved");document.getElementById("proposalview").scrollIntoView({behavior:"smooth",block:"start"})}catch(e){say(e.message)}}
document.getElementById("approve").onclick=async function(){if(!currentProposal)return;if(!confirm("Saya sudah memeriksa seluruh diff dan menyetujui patch persis dengan SHA-256 "+currentProposal.patch_sha256+". Terbitkan approval receipt?"))return;try{const d=await api("/repair/proposals/"+currentProposal.proposal_id+"/approve",{method:"POST",body:JSON.stringify({confirm_owner_approval:true})});say("Proposal approved. Receipt berlaku "+d.expires_in_seconds+" detik. Lanjutkan queue secara terpisah.");await refresh();await reviewProposal(currentProposal.proposal_id)}catch(e){say(e.message)}};
document.getElementById("queue").onclick=async function(){if(!currentProposal)return;if(!confirm("Masukkan patch yang sudah disetujui ke antrean runner? Runner hanya dapat membuat Draft PR setelah validasi; tidak merge atau deploy."))return;try{const d=await api("/repair/proposals/"+currentProposal.proposal_id+"/queue",{method:"POST",body:JSON.stringify({confirm_owner_queue:true})});say("Queued: "+d.request_id+" · runner akan mengambilnya pada polling berikutnya.");await refresh();await reviewProposal(currentProposal.proposal_id)}catch(e){say(e.message)}};
document.getElementById("closeview").onclick=function(){document.getElementById("proposalview").classList.add("hidden");currentProposal=null};
document.getElementById("connect").onclick=connect;document.getElementById("reload").onclick=refresh;document.getElementById("lock").onclick=lock;
if(apiKey){document.getElementById("key").value=apiKey;connect()}
</script></body></html>
"""
